export default {"html":"<p data-line=\"0\" class=\"code-line\">This article is part of the <a href=\"https://adventar.org/calendars/7114\" target=\"_blank\" rel=\"noopener noreferrer\">Ionic Framework / Capacitor / Stencil Advent Calendar 2021 Advent Calendar 2021</a>.</p>\n<hr data-line=\"2\" class=\"code-line\">\n<p data-line=\"4\" class=\"code-line\"><a href=\"https://stenciljs.jp/\" target=\"_blank\" rel=\"noopener noreferrer\">StencilJS</a>, a web component output library, includes a router, so you can build a web app with it alone. It also has prerender support, so you can output a static site with SSG.</p>\n<p data-line=\"6\" class=\"code-line\">The StencilJS website itself is built with StencilJS.</p>\n<p data-line=\"8\" class=\"code-line\"><a href=\"https://stenciljs.jp/\" rel=\"noopener noreferrer\" target=\"_blank\">https://stenciljs.jp/</a><a href=\"https://stenciljs.jp/\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://stenciljs.jp/</a></p>\n<p data-line=\"10\" class=\"code-line\">However, after verifying it locally, deploying to Firebase Hosting with the default settings caused some files to return 404 Not Found, so I am documenting how to fix that.</p>\n<p data-line=\"12\" class=\"code-line\">First, remove hashes from StencilJS output and set <code>noCache</code> to control caching at the same time. Configure <code>stencil.config.ts</code> as follows.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span> export const config: Config = {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   hashFileNames: false,</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   enableCache: false,</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   globalStyle: 'src/global/app.scss',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   globalScript: 'src/global/app.ts',</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"22\" class=\"code-line\">Also configure <code>firebase.json</code> as follows. Even with prerender, you need rewrites because it is still an SPA.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"24\"><span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  \"hosting\"</span><span style=\"color:#E1E4E8\">: {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    \"public\"</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">\"www\"</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    \"ignore\"</span><span style=\"color:#E1E4E8\">: [</span><span style=\"color:#9ECBFF\">\"firebase.json\"</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">\"**/.*\"</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">\"**/node_modules/**\"</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    \"rewrites\"</span><span style=\"color:#E1E4E8\">: [</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        \"source\"</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">\"**\"</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        \"destination\"</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">\"/index.html\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"39\" class=\"code-line\">Simple enough. See you next time.</p>\n","headings":[]} as const;
